"""Source/metadata/archive/checkpoint reader. Original process birth, no process control."""
from pathlib import Path
import argparse,hashlib,importlib.util,json,zipfile
from native_E149_recovery_contract import R,FORMAL,read,sha,encoded,require,check_pins
T=R/'維護工具'
def module(name,path):
 spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
def verify(qp,master,chunk):
 q=read(qp);check_pins(q['source_pins']);check_pins(q['normal_product_pins']);validator=module('shape67_source_reader',T/'qualify-native-E149-decay71-meteor74.py');c,k,prior,cov,proof,products=validator.validate(Path(q['compile_run'])/'cohort.json');require(q['metadata_products']==products and q['current_source_coverage']==cov and q['observed_actual_exit_code']==0 and q['observed_original_tool_chunk']==chunk and q['compiler_exit_codes']==[0]*18,'actual compiler identity differs');process=module('birth_first_original_reader',T/'native_E149_process_birth_readonly.py');observations=[process.original_terminal(r)for r in [c['pipeline']]+[r['original_process']for r in c['compiler_runs']]]
 require(all(q[n]for n in ['decay71_request_and_finite_visual_integrated','meteor74_request_and_class1_first_target_integrated','server_only_cost_probability_and_status']),'source integration differs');require((q['effective_overlay_files'],q['runtime_modules'],q['Rust_QA_files'],q['Java_files'],q['resolved_module_path_attributes'],q['original_nested_paths_preserved'],q['new_tests_written'],q['retained_skill_tests_written'])==(42,28,11,3,371,6,14,372),'inventory differs');require(q['tests_executed']==q['new_sessions']==q['desktop_inputs']==q['WAV_playbacks']==0 and not any(q[n]for n in ['actual_GAME_overrides_observed','PEs_linked','outputs_executed','production_applied','canonical_registry_selected','GUI_verified','old_source_success_transferred','whole_goal_complete']),'scope differs');require(q['request_registered_ids']==[] and cov['recognized_count']==78 and cov['missing_request_count']==102,'coverage differs');require(sha(q['raw_archive'])==q['raw_archive_sha256'],'archive differs')
 with zipfile.ZipFile(q['raw_archive'])as z:require(len(z.namelist())==len(q['raw_archive_files']) and all(hashlib.sha256(z.read(Path(p).relative_to(R).as_posix())).hexdigest().upper()==h for p,h in q['raw_archive_files'].items()),'raw members differ')
 rb=read(qp.with_name('readback.json'));require(rb['qualification_sha256']==sha(qp) and len(rb['after_files'])==8 and all(sha(R/n)==h for n,h in rb['after_files'].items()),'checkpoints differ')
 with zipfile.ZipFile(qp.with_name('before.zip'))as z:require(all(hashlib.sha256(z.read(n)).hexdigest().upper()==h for n,h in rb['before_files'].items()),'before archive differs')
 w=read(R/'工作佇列.json');ref=w['current_E149_decay71_meteor74_development'];require(ref['qualification']==str(qp) and ref['qualification_sha256']==sha(qp) and w['current_user_requested_goal']['test_execution_deferred_by_user'] and w['current_user_requested_goal']['desktop_automation_deferred_by_user'] and not w['active_workloads'] and not w['active_workload_sessions'] and not w['source_and_corresponding_QA_frozen'],'phase differs');require(sha(w['current_formal_reference_identity']['formal'])==FORMAL and q['current_fixture_binding_unchanged']==prior['current_fixture_binding_unchanged'] and q['current_formal_suite_unchanged']==prior['current_formal_suite_unchanged'] and q['canonical_registry_unchanged']==w['current_isolated_development']['candidates'],'formal/registry/G06 differs');report=R.parent/'LiTo381-總開發報告.md';m=read(master);require(sha(report)==m['after_sha256'] and report.read_bytes()==master.with_name('after.md').read_bytes(),'master differs');text=report.read_text('utf-8-sig');require(all(v in text for v in ['#71','#74','386','78／剩102','第一目標','測試與桌面操作暫緩']),'master scope absent')
 result=dict(qualification=str(qp),qualification_sha256=sha(qp),original_process_observations=observations,original_processes_checked=len(observations),process_control_calls=0,restarts=0,metadata_commands=18,new_cases_written=14,tests_executed=0,normal_inputs_checked=1049,unchanged_registry_and_G06=True,eight_checkpoint_readback=str(qp.with_name('readback.json')),master_readback=str(master),master_report_sha256=sha(report),recognized_requests=78,remaining_request_ids=102,whole_goal_complete=False);qp.with_name('final-readback.json').write_bytes(encoded(result));print(json.dumps({k:v for k,v in result.items()if k!='original_process_observations'},ensure_ascii=False))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('qualification',type=Path);p.add_argument('--master-readback',type=Path,required=True);p.add_argument('--observed-original-tool-chunk',required=True);a=p.parse_args();verify(a.qualification,a.master_readback,a.observed_original_tool_chunk)
